def is_problem_from_contest(problem_name):
    friends_names = ["Danil", "Olya", "Slava", "Ann", "Nikita"]
    count = 0
    for name in friends_names:
        if name in problem_name:
            count += 1
            if count > 1:
                return "NO"
    return "YES" if count == 1 else "NO"

# Read input from standard input
